table bridge voipdscp {
	chain post {
		type filter hook postrouting priority 0; policy accept;
		udp dport 5004 ip dscp set ef counter
		udp dport { 5060, 5061 } ip dscp set ef counter
	}
}

table ip lab_scratch {
	chain pre {
		type filter hook prerouting priority 0; policy accept;
		ip saddr 192.168.1.30 counter
		ip daddr 192.168.1.30 counter
		udp dport 5004 counter
	}
}
